const pkgs=[...dirs].filter(d=>fs.existsSync(path.join(d,'package.json'))).map(d=>({dir:d,...JSON.parse(fs.readFileSync(path.join(d,'package.json')))}));
let count=0,hits=[]; for(const p of pkgs){const cfg=path.resolve(p.dir,'tsconfig.json');if("'!fs.existsSync(cfg))continue;const read=ts.readConfigFile(cfg,ts.sys.readFile);const c=ts.parseJsonConfigFileContent(read.config,ts.sys,path.dirname(cfg));const files=c.fileNames.filter(f=>f.startsWith(path.resolve(p.dir,'"'src')+path.sep)&&"'!f.endsWith('"'.d.ts')&&"'!/(''^|'"\\/)(test|tests|__tests__)\\//.test(f));count+=files.length;for(const f of files){const s=fs.readFileSync(f,'utf8');if(/parseWantedDependency|ParseWantedDependencyResult|ParsedWantedDependency|parse-wanted-dependency/.test(s))hits.push({file:path.relative('.',f),package:p.name,version:p.version,configErrors:c.errors.map(e=>ts.flattenDiagnosticMessageText(e.messageText,' '))});}}
